<?php defined('ABSPATH') || exit; $headings=''; foreach (['name'=>__('Name','azwp-passkeys'),'model'=>__('Authenticator','azwp-passkeys'),'added'=>__('Added','azwp-passkeys'),'last-used'=>__('Last used','azwp-passkeys')] as $key=>$label) $headings.='<th scope="col" class="manage-column column-'.$key.($key==='name'?' column-primary':'').'">'.esc_html($label).'</th>'; ?>
<div class="azwp-passkeys azwp-passkeys-table-wrap" id="<?php echo esc_attr($instance); ?>" data-azwp-passkeys="list" data-target="<?php echo esc_attr($target_id); ?>" data-nonce="<?php echo esc_attr($nonce); ?>" data-can-manage="<?php echo $can_manage?'1':'0'; ?>">
